        public StrangerSystem()
        {
            this.Interval = 0;
            myPid = (uint)Process.GetCurrentProcess().Id;

            string gameDir = "";
            try
            {
                gameDir = Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName);
            }
            catch (Exception)
            {
                gameDir = Directory.GetCurrentDirectory();
            }

            logPath = Path.Combine(gameDir, "scripts\\GreetTauntRob.log");

            try
            {
                if (File.Exists(logPath) && new FileInfo(logPath).Length > 256 * 1024) File.Delete(logPath);
            }
            catch (Exception) { }

            Log("=== StrangerSystem build 2026-10-03 v23 | DebugStage=" + DebugStage + " | HoldWhileAiming=" + HoldWhileAiming + " | BlockEvents=" + BlockEventsDuringHold + " | memory playback=" + UseMemoryPlayback + " ===");

            string episodeFolder = DetectEpisodeFolder();
            dialogueRoot = Path.Combine(Path.Combine(gameDir, DialogueFolder), episodeFolder);
            if (!Directory.Exists(dialogueRoot)) Log("Dialogue folder does not exist yet: " + dialogueRoot);

            string[] greetFiles = LoadBank(dialogueRoot, "Greet");
            greetBeginBank.Files = FilterByName(greetFiles, "GREETBEGIN");
            greetEndBank.Files = FilterByName(greetFiles, "GREETEND");
            tauntBank.Files = LoadBank(dialogueRoot, "Taunt");
            robBank.Files = LoadBank(dialogueRoot, "Rob");
            robAfterBank.Files = LoadBank(dialogueRoot, "Rob2");

            Log("Loaded audio: greetbegin=" + greetBeginBank.Files.Length + " greetend=" + greetEndBank.Files.Length + " taunt=" + tauntBank.Files.Length + " rob=" + robBank.Files.Length + " robafter=" + robAfterBank.Files.Length + " from " + dialogueRoot);
            LoadReplies(Path.Combine(gameDir, DialogueFolder), dialogueRoot, episodeFolder);

            LoadFactions(Path.Combine(gameDir, DialogueFolder));
            LoadTextTextures(gameDir);
            LoadIcons();
            PusherAnnounce();
            this.PerFrameDrawing += new GraphicsEventHandler(OnDraw);
            this.Tick += new EventHandler(OnTick);
        }

        string DetectEpisodeFolder()
        {
            string raw = "?";
            int num = -1;
            try
            {
                object ep = Game.CurrentEpisode;
                raw = ep.ToString();
                try { num = Convert.ToInt32(ep); }
                catch (Exception) { }
            }
            catch (Exception ex)
            {
                Log("Episode detection failed (" + ex.Message + "), assuming IV");
                return "IV";
            }

            string up = raw.ToUpper();
            string folder = "IV";
            if (up.Contains("TLAD") || up.Contains("LOST")) folder = "TLAD";
            else if (up.Contains("TBOGT") || up.Contains("GAY") || up.Contains("TONY")) folder = "TBoGT";
            else if (num == 1) folder = "TLAD";
            else if (num == 2) folder = "TBoGT";

            Log("Episode detected: Game.CurrentEpisode = " + raw + " (number " + num + ") -> dialogue folder '" + folder + "'");
            return folder;
        }

        string[] FilterByName(string[] files, string text)
        {
            List<string> list = new List<string>();
            foreach (string f in files)
            {
                if (Path.GetFileName(f).ToUpper().Contains(text.ToUpper())) list.Add(f);
            }
            return list.ToArray();
        }

        string[] LoadBank(string root, string name)
        {
            List<string> list = new List<string>();
            try
            {
                string sub = Path.Combine(root, name);
                if (Directory.Exists(sub))
                    AddAudio(list, Directory.GetFiles(sub));

                if (Directory.Exists(root))
                {
                    string[] top = Directory.GetFiles(root);
                    List<string> match = new List<string>();
                    foreach (string f in top)
                    {
                        if (Path.GetFileName(f).ToLower().StartsWith(name.ToLower()))
                            match.Add(f);
                    }
                    AddAudio(list, match.ToArray());
                }
            }
            catch (Exception ex)
            {
                Log("LoadBank error: " + ex.Message);
            }
            list.Sort();
            for (int i = 0; i < list.Count; i++) list[i] = PrepareVoiceFile(list[i]);
            return list.ToArray();
        }

        List<string> scaledFiles = new List<string>();

        Dictionary<string, byte[]> voiceData = new Dictionary<string, byte[]>();
        Dictionary<string, int> voiceLenMs = new Dictionary<string, int>();
        System.Media.SoundPlayer voicePlayer;
        System.IO.MemoryStream voiceStream;

        int PlayFromMemory(string file)
        {
            mciSendString("close nikoVoice", null, 0, IntPtr.Zero);
            try
            {
                if (voicePlayer != null) { voicePlayer.Stop(); voicePlayer.Dispose(); voicePlayer = null; }
                if (voiceStream != null) { voiceStream.Dispose(); voiceStream = null; }
                voiceStream = new System.IO.MemoryStream(voiceData[file]);
                voicePlayer = new System.Media.SoundPlayer(voiceStream);
                voicePlayer.Play();
            }
            catch (Exception ex)
            {
                Log("In-memory playback failed: " + ex.Message);
                Game.DisplayText("Could not play audio: " + Path.GetFileName(file), 4000);
                return 0;
            }

            int len = voiceLenMs[file];
            if (len < 300) len = 300;
            if (len > 8000) len = 8000;
            Log("Playing " + Path.GetFileName(file) + " (" + len + " ms, from memory)");
            return len;
        }

        string HexHead(byte[] b)
        {
            int n = Math.Min(16, b.Length);
            byte[] head = new byte[n];
            Array.Copy(b, head, n);
            return BitConverter.ToString(head);
        }

        string DetectAudioKind(byte[] b, out string ext)
        {
            ext = null;
            if (b.Length < 12) return "file too small / empty";
            string a4 = Encoding.ASCII.GetString(b, 0, 4);
            if (a4.StartsWith("ID3") || (b[0] == 0xFF && (b[1] & 0xE0) == 0xE0)) { ext = ".mp3"; return "MP3"; }
            if (a4 == "OggS") { ext = ".ogg"; return "Ogg (Vorbis/Opus)"; }
            if (a4 == "fLaC") { ext = ".flac"; return "FLAC"; }
            if (Encoding.ASCII.GetString(b, 4, 4) == "ftyp") { ext = ".m4a"; return "MP4 / M4A (AAC)"; }
            if (a4 == "RF64") return "RF64 wav (not supported)";
            if (a4 == "RIFX") return "big-endian wav (not supported)";
            if (a4 == "FORM") { ext = ".aif"; return "AIFF"; }
            if (b[0] == 0x1A && b[1] == 0x45 && b[2] == 0xDF && b[3] == 0xA3) { ext = ".webm"; return "WebM / Matroska"; }
            return "unknown format";
        }

        string PrepareVoiceFile(string file)
        {
            try
            {
                if (Path.GetExtension(file).ToLower() != ".wav") return file;

                string dir = Path.Combine(Path.GetTempPath(), "StrangerSystemVoice");
                string tag = Path.GetFileName(Path.GetDirectoryName(file));
                string outPath = Path.Combine(dir, VoiceVolume + "_" + tag + "_" + Path.GetFileName(file));

                double gain = VoiceVolume / 1000.0;
                byte[] raw = File.ReadAllBytes(file);
                byte[] converted = ToPcm16Wav(raw, gain);
                if (converted == null)
                {
                    string altExt;
                    string kind = DetectAudioKind(raw, out altExt);
                    Log("NOT A STANDARD WAV: " + tag + "\\" + Path.GetFileName(file) + "  (" + lastWavInfo + ")  looks like: " + kind + "  first bytes: " + HexHead(raw));
                    if (altExt != null)
                    {
                        Directory.CreateDirectory(dir);
                        string alt = Path.Combine(dir, "raw_" + tag + "_" + Path.GetFileNameWithoutExtension(file) + altExt);
                        File.WriteAllBytes(alt, raw);
                        Log("Trying it as " + altExt + " -> " + alt + "   (volume cannot be lowered for this one; re-export it as a real .wav)");
                        return alt;
                    }
                    return file;
                }
                if (UseMemoryPlayback)
                {
                    int ch = BitConverter.ToInt16(converted, 22);
                    int rate = BitConverter.ToInt32(converted, 24);
                    int ms = (int)((long)(converted.Length - 44) * 1000L / (long)(rate * ch * 2));
                    voiceData[file] = converted;
                    voiceLenMs[file] = ms;
                    Log("Voice file ready (in memory): " + tag + "\\" + Path.GetFileName(file) + "  [" + lastWavInfo + "]");
                    return file;
                }

                Directory.CreateDirectory(dir);
                File.WriteAllBytes(outPath, converted);
                scaledFiles.Add(outPath);
                Log("Voice file ready: " + tag + "\\" + Path.GetFileName(file) + "  [" + lastWavInfo + "]");
                return outPath;
            }
            catch (Exception ex)
            {
                Log("Voice file preparation failed for " + file + ": " + ex.Message);
                return file;
            }
        }

        string lastWavInfo = "";

        byte[] ToPcm16Wav(byte[] src, double gain)
        {
            lastWavInfo = "";
            if (src.Length < 44) { lastWavInfo = "file too small"; return null; }
            if (src[0] != 'R' || src[1] != 'I' || src[2] != 'F' || src[3] != 'F') { lastWavInfo = "not a RIFF wav"; return null; }
            if (src[8] != 'W' || src[9] != 'A' || src[10] != 'V' || src[11] != 'E') { lastWavInfo = "not a WAVE file"; return null; }

            int pos = 12;
            int tag = 0, bits = 0, channels = 0, rate = 0, dataStart = -1, dataLen = 0;
            while (pos + 8 <= src.Length)
            {
                string id = Encoding.ASCII.GetString(src, pos, 4);
                int size = BitConverter.ToInt32(src, pos + 4);
                int body = pos + 8;
                if (id == "fmt " && body + 16 <= src.Length)
                {
                    tag = BitConverter.ToUInt16(src, body);
                    channels = BitConverter.ToUInt16(src, body + 2);
                    rate = BitConverter.ToInt32(src, body + 4);
                    bits = BitConverter.ToUInt16(src, body + 14);
                    if (tag == 0xFFFE && size >= 26 && body + 26 <= src.Length) tag = BitConverter.ToUInt16(src, body + 24);
                }
                else if (id == "data")
                {
                    dataStart = body;
                    dataLen = size;
                    if (dataLen < 0 || dataStart + dataLen > src.Length) dataLen = src.Length - dataStart;
                    break;
                }
                if (size < 0) { lastWavInfo = "bad chunk size"; return null; }
                pos = body + size + (size & 1);
            }
            lastWavInfo = "format tag " + tag + ", " + bits + "-bit, " + channels + " ch, " + rate + " Hz";
            if (dataStart < 0 || channels < 1 || rate < 1000) return null;

            int bytesPer = bits / 8;
            bool isInt = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32));
            bool isFloat = (tag == 3 && (bits == 32 || bits == 64));
            if (!isInt && !isFloat) return null;

            int count = dataLen / bytesPer;
            byte[] outData = new byte[count * 2];
            for (int n = 0; n < count; n++)
            {
                int p = dataStart + n * bytesPer;
                double v;
                if (isFloat)
                {
                    v = (bits == 32) ? BitConverter.ToSingle(src, p) : BitConverter.ToDouble(src, p);
                }
                else if (bits == 8)
                {
                    v = (src[p] - 128) / 128.0;
                }
                else if (bits == 16)
                {
                    v = BitConverter.ToInt16(src, p) / 32768.0;
                }
                else if (bits == 24)
                {
                    int t = src[p] | (src[p + 1] << 8) | (src[p + 2] << 16);
                    if ((t & 0x800000) != 0) t -= 0x1000000;
                    v = t / 8388608.0;
                }
                else
                {
                    v = BitConverter.ToInt32(src, p) / 2147483648.0;
                }

                int s16 = (int)Math.Round(v * gain * 32767.0);
                if (s16 > 32767) s16 = 32767;
                if (s16 < -32768) s16 = -32768;
                outData[n * 2] = (byte)(s16 & 0xFF);
                outData[n * 2 + 1] = (byte)((s16 >> 8) & 0xFF);
            }

            byte[] wav = new byte[44 + outData.Length];
            Encoding.ASCII.GetBytes("RIFF").CopyTo(wav, 0);
            BitConverter.GetBytes(36 + outData.Length).CopyTo(wav, 4);
            Encoding.ASCII.GetBytes("WAVE").CopyTo(wav, 8);
            Encoding.ASCII.GetBytes("fmt ").CopyTo(wav, 12);
            BitConverter.GetBytes(16).CopyTo(wav, 16);
            BitConverter.GetBytes((short)1).CopyTo(wav, 20);
            BitConverter.GetBytes((short)channels).CopyTo(wav, 22);
            BitConverter.GetBytes(rate).CopyTo(wav, 24);
            BitConverter.GetBytes(rate * channels * 2).CopyTo(wav, 28);
            BitConverter.GetBytes((short)(channels * 2)).CopyTo(wav, 32);
            BitConverter.GetBytes((short)16).CopyTo(wav, 34);
            Encoding.ASCII.GetBytes("data").CopyTo(wav, 36);
            BitConverter.GetBytes(outData.Length).CopyTo(wav, 40);
            outData.CopyTo(wav, 44);
            return wav;
        }

        void AddAudio(List<string> list, string[] files)
        {
            foreach (string f in files)
            {
                string ext = Path.GetExtension(f).ToLower();
                if ((ext == ".wav" || ext == ".mp3" || ext == ".wma") && !list.Contains(f))
                    list.Add(f);
            }
        }

        long Now()
        {
            return clock.ElapsedMilliseconds;
        }

        static readonly bool EnableLogging = true;

        void Log(string msg)
        {
            if (!EnableLogging) return;
            if (msg == lastLog) return;
            lastLog = msg;
            try
            {
                File.AppendAllText(logPath, DateTime.Now.ToString("HH:mm:ss") + "  " + msg + "\r\n");
            }
            catch (Exception) { }
        }

        void Later(int ms, Job0 action)
        {
            Job j = new Job();
            j.Due = Now() + ms;
            j.Run = action;
            jobs.Add(j);
        }

        void RunJobs(long now)
        {
            if (jobs.Count == 0) return;
            List<Job> due = new List<Job>();
            foreach (Job j in jobs)
            {
                if (j.Due <= now) due.Add(j);
            }
            foreach (Job j in due)
            {
                jobs.Remove(j);
                try { j.Run(); }
                catch (Exception ex) { Log("Job error: " + ex.Message); }
            }
        }

