        System.Reflection.MemberInfo handleMember;
        bool handleSearched;

        System.Reflection.MemberInfo FindHandleMember(Ped p)
        {
            System.Reflection.BindingFlags flags =
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.Public |
                System.Reflection.BindingFlags.NonPublic |
                System.Reflection.BindingFlags.DeclaredOnly;

            System.Reflection.MemberInfo named = null;
            Type t = p.GetType();
            while (t != null && t != typeof(object))
            {
                foreach (System.Reflection.FieldInfo f in t.GetFields(flags))
                {
                    if (f.FieldType != typeof(int) && f.FieldType != typeof(uint)) continue;
                    Log("handle candidate FIELD " + t.Name + "." + f.Name);
                    if (named == null && LooksLikeHandle(f.Name)) named = f;
                }
                foreach (System.Reflection.PropertyInfo pr in t.GetProperties(flags))
                {
                    if (!pr.CanRead || pr.GetIndexParameters().Length != 0) continue;
                    if (pr.PropertyType != typeof(int) && pr.PropertyType != typeof(uint)) continue;
                    Log("handle candidate PROPERTY " + t.Name + "." + pr.Name);
                    if (named == null && LooksLikeHandle(pr.Name)) named = pr;
                }
                t = t.BaseType;
            }

            if (named == null) Log("No handle member found on Ped; falling back to Equals()");
            else Log("Using handle member: " + named.DeclaringType.Name + "." + named.Name);
            return named;
        }

        bool LooksLikeHandle(string name)
        {
            string n = name.ToLower();
            return n.Contains("value") || n.Contains("handle") || n == "id" || n.Contains("pointer") || n.Contains("ptr") || n.Contains("index");
        }

        int HandleOf(Ped p)
        {
            if (!handleSearched)
            {
                handleSearched = true;
                handleMember = FindHandleMember(p);
            }
            if (handleMember == null) return int.MinValue;
            try
            {
                object v;
                System.Reflection.FieldInfo fi = handleMember as System.Reflection.FieldInfo;
                if (fi != null) v = fi.GetValue(p);
                else v = ((System.Reflection.PropertyInfo)handleMember).GetValue(p, null);
                return Convert.ToInt32(v);
            }
            catch (Exception) { return int.MinValue; }
        }

        bool SamePed(Ped a, Ped b)
        {
            if (object.ReferenceEquals(a, null) || object.ReferenceEquals(b, null)) return false;
            int ha = HandleOf(a);
            int hb = HandleOf(b);
            if (ha != int.MinValue && hb != int.MinValue) return ha == hb;
            return a.Equals(b);
        }

        PedState GetState(Ped p, long now)
        {
            int h = HandleOf(p);
            foreach (PedEntry e in entries)
            {
                bool same;
                if (h != int.MinValue && e.Handle != int.MinValue) same = (e.Handle == h);
                else same = e.Ped.Equals(p);
                if (same)
                {
                    e.Ped = p;
                    e.State.LastSeen = now;
                    return e.State;
                }
            }
            PedEntry ne = new PedEntry();
            ne.Handle = h;
            ne.Ped = p;
            ne.State = new PedState();
            ne.State.LastSeen = now;
            entries.Add(ne);
            return ne.State;
        }

        void PurgeStates(long now)
        {
            if (now < nextPurge) return;
            nextPurge = now + 30000;
            entries.RemoveAll(delegate(PedEntry e) { return now - e.State.LastSeen > 120000; });
        }

        bool GameHasFocus()
        {
            try
            {
                uint pid;
                GetWindowThreadProcessId(GetForegroundWindow(), out pid);
                return pid == myPid;
            }
            catch (Exception) { return true; }
        }

        float GetAspect()
        {
            try
            {
                RECT r;
                if (GetClientRect(GetForegroundWindow(), out r))
                {
                    int w = r.Right - r.Left;
                    int h = r.Bottom - r.Top;
                    if (w > 0 && h > 0) return (float)w / (float)h;
                }
            }
            catch (Exception) { }
            return 16.0f / 9.0f;
        }

        uint XGet(uint idx, out XINPUT_STATE s)
        {
            s = new XINPUT_STATE();
            if (xiMode == 14)
            {
                try { return XInputGetState14(idx, out s); }
                catch (Exception) { xiMode = 13; }
            }
            if (xiMode == 13)
            {
                try { return XInputGetState13(idx, out s); }
                catch (Exception) { xiMode = -1; }
            }
            return 1167;
        }

        Inp ReadInput(bool focused)
        {
            Inp r = new Inp();
            if (!focused) return r;

            if (xiMode != -1)
            {
                XINPUT_STATE s;
                bool got = false;
                if (XGet(padIndex, out s) == 0) got = true;
                else
                {
                    for (uint i = 0; i < 4; i++)
                    {
                        if (XGet(i, out s) == 0) { padIndex = i; got = true; break; }
                    }
                }
                if (got)
                {
                    r.Aim = s.Gamepad.bLeftTrigger > AimTriggerThreshold;
                    r.Greet = (s.Gamepad.wButtons & 0x0004) != 0;
                    r.Taunt = (s.Gamepad.wButtons & 0x0008) != 0;
                    r.Rob = (s.Gamepad.wButtons & 0x0100) != 0;
                    r.Face = (s.Gamepad.wButtons & 0xF000) != 0;
                    r.Fire = s.Gamepad.bRightTrigger > AimTriggerThreshold;
                }
            }

            if (EnableKeyboardFallback && (GetAsyncKeyState(VK_HOLD) & 0x8000) != 0)
            {
                r.Aim = true;
                if ((GetAsyncKeyState(VK_GREET) & 0x8000) != 0) r.Greet = true;
                if ((GetAsyncKeyState(VK_TAUNT) & 0x8000) != 0) r.Taunt = true;
                if ((GetAsyncKeyState(VK_ROB) & 0x8000) != 0) r.Rob = true;
                if ((GetAsyncKeyState(VK_SELL) & 0x8000) != 0) r.Sell = true;
            }
            if ((GetAsyncKeyState(0x01) & 0x8000) != 0) r.Fire = true;
            return r;
        }

        string PickLine(VoiceBank bank)
        {
            int n = bank.Files.Length;
            if (n == 0) return null;
            int idx = 0;
            if (n > 1)
            {
                do { idx = rng.Next(n); } while (idx == bank.Last);
            }
            bank.Last = idx;
            return bank.Files[idx];
        }

        int PlayVoice(string file)
        {
            if (voiceData.ContainsKey(file)) return PlayFromMemory(file);

            mciSendString("close nikoVoice", null, 0, IntPtr.Zero);

            int err1 = mciSendString("open \"" + file + "\" type mpegvideo alias nikoVoice", null, 0, IntPtr.Zero);
            int err2 = 0;
            if (err1 != 0) err2 = mciSendString("open \"" + file + "\" alias nikoVoice", null, 0, IntPtr.Zero);
            if (err1 != 0 && err2 != 0)
            {
                StringBuilder msg = new StringBuilder(256);
                mciGetErrorString(err2, msg, 256);
                Log("Could not open audio: " + file + "  (" + msg.ToString() + ")");
                Game.DisplayText("Could not play audio: " + Path.GetFileName(file), 4000);
                return 0;
            }

            mciSendString("set nikoVoice time format milliseconds", null, 0, IntPtr.Zero);
            if (!scaledFiles.Contains(file))
            {
                int vr = mciSendString("setaudio nikoVoice volume to " + VoiceVolume, null, 0, IntPtr.Zero);
                if (vr != 0) LogOnce("vol", "setaudio volume failed (code " + vr + "): use .wav files for volume control");
            }

            int len = 1500;
            StringBuilder sb = new StringBuilder(64);
            if (mciSendString("status nikoVoice length", sb, 64, IntPtr.Zero) == 0)
            {
                int parsed;
                if (int.TryParse(sb.ToString().Trim(), out parsed) && parsed > 0) len = parsed;
            }
            if (len > 8000) len = 8000;
            Log("Playing " + Path.GetFileName(file) + " (" + len + " ms)");
            mciSendString("play nikoVoice", null, 0, IntPtr.Zero);
            return len;
        }

        class ReplyCat
        {
            public string[] Phrases;
            public bool Shuffle;
        }

        Dictionary<string, ReplyCat> replyCats = new Dictionary<string, ReplyCat>();
        Dictionary<string, string> replyMap = new Dictionary<string, string>();

        void AddCat(string name, bool shuffle, params string[] phrases)
        {
            ReplyCat rc = new ReplyCat();
            rc.Phrases = phrases;
            rc.Shuffle = shuffle;
            replyCats[name] = rc;
        }

        void DefineDefaultReplies()
        {
            AddCat("hello", false, "GENERIC_HI", "CHAT_RESP");
            AddCat("farewell", false, "GENERIC_BYE", "THANKS", "GENERIC_YES");
            AddCat("annoyed", false, "GENERIC_NO", "GENERIC_DEJECTED", "GENERIC_BYE");
            AddCat("remark", false, "GENERIC_YES", "GENERIC_DEJECTED", "GENERIC_BYE");
            AddCat("thanks", false, "THANKS", "GENERIC_BYE");
            AddCat("insult", true, "GENERIC_FUCK_OFF", "JEERING", "SHIT", "HECKLE");
            AddCat("challenge", true, "INTIMIDATE_RESP", "FIGHT", "GENERIC_FUCK_OFF", "JEERING");
            AddCat("demand", true, "SHOCKED", "SURPRISED", "GENERIC_NO", "GENERIC_DEJECTED", "SHIT");
        }

        void LoadReplies(string dialogueRootAll, string gameFolder, string episode)
        {
            DefineDefaultReplies();

            string allPath = Path.Combine(dialogueRootAll, "replies.txt");
            string gamePath = Path.Combine(gameFolder, "replies.txt");
            bool any = false;
            if (File.Exists(allPath)) { ReadRepliesFile(allPath, episode); any = true; }
            if (File.Exists(gamePath)) { ReadRepliesFile(gamePath, episode); any = true; }

            if (!any) Log("No replies.txt in " + dialogueRootAll + " (using the built-in reply types)");
            else Log("Reply mapping for " + episode + ": " + replyMap.Count + " line(s)");
        }

        void ReadRepliesFile(string path, string episode)
        {
            try
            {
                string section = "";
                foreach (string raw in File.ReadAllLines(path))
                {
                    string line = raw.Trim();
                    if (line.Length == 0 || line.StartsWith("#") || line.StartsWith("//")) continue;

                    if (line.StartsWith("[") && line.EndsWith("]"))
                    {
                        section = line.Substring(1, line.Length - 2).Trim().ToUpper();
                        continue;
                    }
                    if (section.Length > 0 && section != "ALL" && section != episode.ToUpper()) continue;

                    int eq = line.IndexOf('=');
                    if (eq < 1) continue;

                    string key = line.Substring(0, eq).Trim();
                    string val = line.Substring(eq + 1).Trim();

                    if (key.StartsWith("@"))
                    {
                        bool shuffle = false;
                        int bar = val.IndexOf('|');
                        if (bar >= 0)
                        {
                            shuffle = val.Substring(bar + 1).Trim().ToLower() == "shuffle";
                            val = val.Substring(0, bar);
                        }
                        List<string> ph = new List<string>();
                        foreach (string part in val.Split(','))
                        {
                            string t = part.Trim().ToUpper();
                            if (t.Length > 0) ph.Add(t);
                        }
                        if (ph.Count > 0) AddCat(key.Substring(1).Trim().ToLower(), shuffle, ph.ToArray());
                    }
                    else
                    {
                        replyMap[key.ToUpper()] = val.ToLower();
                    }
                }
            }
            catch (Exception ex) { Log("replies.txt could not be read (" + path + "): " + ex.Message); }
        }

        void SayFor(Ped p, string file, string defaultType)
        {
            string type = defaultType;
            string baseName = Path.GetFileNameWithoutExtension(file).ToUpper();
            bool found = false;
            foreach (KeyValuePair<string, string> kv in replyMap)
            {
                if (baseName == kv.Key || baseName.EndsWith("_" + kv.Key)) { type = kv.Value; found = true; break; }
            }
            if (!found)
            {
                foreach (KeyValuePair<string, string> kv in replyMap)
                {
                    if (!kv.Key.EndsWith("*")) continue;
                    string prefix = kv.Key.Substring(0, kv.Key.Length - 1);
                    if (prefix.Length > 0 && (baseName.StartsWith(prefix) || baseName.Contains("_" + prefix))) { type = kv.Value; break; }
                }
            }

            ReplyCat rc;
            if (!replyCats.TryGetValue(type, out rc))
            {
                Log("Unknown reply type '" + type + "' for " + baseName + ", using '" + defaultType + "'");
                type = defaultType;
                if (!replyCats.TryGetValue(type, out rc)) return;
            }

            Log("NPC reply type '" + type + "' for " + baseName);
            string[] order = rc.Shuffle ? Shuffled(rc.Phrases) : (string[])rc.Phrases.Clone();
            SayChain(p, order, 0);
        }

        bool speechCheckBroken;
        bool speechCheckTrusted;

        string[] Shuffled(string[] src)
        {
            string[] a = (string[])src.Clone();
            for (int i = a.Length - 1; i > 0; i--)
            {
                int k = rng.Next(i + 1);
                string t = a[i]; a[i] = a[k]; a[k] = t;
            }
            return a;
        }

        void Say(Ped p, string[] phrases)
        {
            SayChain(p, Shuffled(phrases), 0);
        }

        void SayChain(Ped p, string[] order, int idx)
        {
            if (!Alive(p) || idx >= order.Length || idx >= 4) return;
            string phrase = order[idx];
            try
            {
                Function.Call("SAY_AMBIENT_SPEECH", p, phrase, 1, 1, 0);
                Log("NPC speech requested: " + phrase);
            }
            catch (Exception ex)
            {
                Log("Speech error (" + phrase + "): " + ex.Message);
                return;
            }

            if (speechCheckBroken) return;
            Later(650, delegate
            {
                if (!Alive(p)) return;
                bool speaking;
                try { speaking = Function.Call<bool>("IS_AMBIENT_SPEECH_PLAYING", p); }
                catch (Exception ex)
                {
                    speechCheckBroken = true;
                    Log("IS_AMBIENT_SPEECH_PLAYING unavailable: " + ex.Message);
                    return;
                }

                if (speaking)
                {
                    speechCheckTrusted = true;
                    Log("NPC is speaking: " + phrase);
                    return;
                }
                if (!speechCheckTrusted) { Log("Could not confirm speech for " + phrase); return; }

                Log("No speech for " + phrase + " on this ped, trying the next phrase");
                SayChain(p, order, idx + 1);
            });
        }

        void Scream(Ped p)
        {
            if (!Alive(p)) return;
            Say(p, FearSpeech);
            Later(600, delegate
            {
                if (!Alive(p)) return;
                try { Function.Call("PANIC_SCREAM", p); }
                catch (Exception ex) { LogOnce("panic", "PANIC_SCREAM failed: " + ex.Message); }
            });
        }

        void FacePlayer(Ped p, int standMs)
        {
            try
            {
                Function.Call("TASK_TURN_CHAR_TO_FACE_CHAR", p, Player.Character);
                Later(700, delegate
                {
                    if (Alive(p)) Function.Call("TASK_STAND_STILL", p, standMs);
                });
            }
            catch (Exception ex) { Log("Face error: " + ex.Message); }
        }

        void BlockEvents(Ped p, bool on)
        {
            if (!BlockEventsDuringHold) return;
            try { Function.Call("SET_BLOCKING_OF_NON_TEMPORARY_EVENTS", p, on ? 1 : 0); }
            catch (Exception ex) { LogOnce("block", "SET_BLOCKING_OF_NON_TEMPORARY_EVENTS failed: " + ex.Message); }
        }

        void HoldHandsUp(Ped p, int durationMs)
        {
            if (!Alive(p)) return;
            PedState hs = GetState(p, Now());
            long now = Now();
            long until = now + durationMs;
            if (until > hs.HoldUntil) hs.HoldUntil = until;
            BlockEvents(p, true);
            if (hs.HoldLoopOn) return;
            hs.HoldLoopOn = true;
            hs.ArmsSeen = false;
            hs.LastArmsUp = now + HandsUpRaiseMs;
            // first the game's own hands-up (the arms actually go up), then armsup_loop keeps them there
            bool raised = false;
            try { Function.Call("REQUEST_ANIMS", ArmsUpSet); } catch (Exception) { }
            try { p.Task.HandsUp(HandsUpRaiseMs + 3000); raised = true; } catch (Exception) { }
            if (raised)
            {
                Later(HandsUpRaiseMs, delegate
                {
                    if (!Alive(p)) return;
                    PedState s2 = GetState(p, Now());
                    if (s2.HoldUntil == 0) return;           // let go of meanwhile (he fought back, ran, ...)
                    PlayArmsUp(p, 0, ArmsUpStartPhase);
                });
            }
            else PlayArmsUp(p, 0);
            HoldLoop(p);
        }

        void PlayArmsUp(Ped p, int waited)
        {
            PlayArmsUp(p, waited, 0f);
        }

        void PlayArmsUp(Ped p, int waited, float startPhase)
        {
            if (!Alive(p)) return;
            try
            {
                Function.Call("REQUEST_ANIMS", ArmsUpSet);
                if (Function.Call<bool>("HAVE_ANIMS_LOADED", ArmsUpSet))
                {
                    Function.Call("TASK_PLAY_ANIM", p, ArmsUpAnim, ArmsUpSet, 8.0f, 1, 0, 0, 0, -1);
                    if (startPhase > 0f)
                    {
                        Later(30, delegate
                        {
                            if (!Alive(p)) return;
                            try
                            {
                                if (Function.Call<bool>("IS_CHAR_PLAYING_ANIM", p, ArmsUpSet, ArmsUpAnim))
                                    Function.Call("SET_CHAR_ANIM_CURRENT_TIME", p, ArmsUpSet, ArmsUpAnim, startPhase);
                            }
                            catch (Exception) { }
                        });
                    }
                    return;
                }
            }
            catch (Exception ex)
            {
                LogOnce("armsup", "armsup_loop failed, using the normal hands-up: " + ex.Message);
                try { p.Task.HandsUp(2500); } catch (Exception) { }
                return;
            }
            if (waited >= 2000)
            {
                LogOnce("armsupload", "Animation set 'cop' did not load, using the normal hands-up");
                try { p.Task.HandsUp(2500); } catch (Exception) { }
                return;
            }
            Later(100, delegate { PlayArmsUp(p, waited + 100, startPhase); });
        }

        void HoldLoop(Ped p)
        {
            Later(150, delegate
            {
                if (!Alive(p)) return;
                PedState hs = GetState(p, Now());
                long now = Now();
                if (hs.HoldUntil == 0)
                {
                    hs.HoldLoopOn = false;
                    return;
                }
                if (now >= hs.HoldUntil)
                {
                    hs.HoldUntil = 0;
                    hs.HoldLoopOn = false;
                    BlockEvents(p, false);
                    try { p.Task.ClearAll(); }
                    catch (Exception) { }
                    return;
                }
                bool playing = false;
                try { playing = Function.Call<bool>("IS_CHAR_PLAYING_ANIM", p, ArmsUpSet, ArmsUpAnim); }
                catch (Exception) { }
                if (playing) hs.ArmsSeen = true;
                else if (hs.ArmsSeen && now - hs.LastArmsUp > 700)
                {
                    PlayArmsUp(p, 0);
                    hs.LastArmsUp = now;
                }
                HoldLoop(p);
            });
        }

        void KeepGunpointHold(Ped ped, PedState st, long now)
        {
            if (st.HoldUntil - now > 800) return;
            HoldHandsUp(ped, 2500);
        }

        void MakeHostile(Ped p)
        {
            if (!Alive(p)) return;
            PedState hs = GetState(p, Now());
            hs.HoldUntil = 0;
            BlockEvents(p, false);
            hs.AggroUntil = Now() + AggroHoldMs;
            p.Task.ClearAll();
            p.Task.FightAgainst(Player.Character);
        }

        void PistolAttack(Ped p)
        {
            if (!Alive(p)) return;
            PedState hs = GetState(p, Now());
            hs.HoldUntil = 0;
            hs.AggroUntil = Now() + AggroHoldMs;
            try { p.Task.ClearAll(); } catch (Exception) { }
            ArmWithPistol(p);
            try
            {
                Function.Call("SET_BLOCKING_OF_NON_TEMPORARY_EVENTS", p, 1);
                Function.Call("SET_CHAR_WILL_USE_COVER", p, 0);
                Function.Call("SET_CHAR_KEEP_TASK", p, 1);
            }
            catch (Exception ex) { LogOnce("pistolprep", "Pistol prep failed: " + ex.Message); }
            Later(350, delegate
            {
                if (!Alive(p)) return;
                ArmWithPistol(p);
                try { p.Task.FightAgainst(Player.Character); }
                catch (Exception ex) { LogOnce("pistolfight", "FightAgainst failed: " + ex.Message); }
                PistolEnforce(p, 0);
            });
            Later(12000, delegate
            {
                if (!Alive(p)) return;
                try { Function.Call("SET_BLOCKING_OF_NON_TEMPORARY_EVENTS", p, 0); } catch (Exception) { }
            });
            Log("Pistol attack started");
        }

        void PistolEnforce(Ped p, int tick)
        {
            Later(600, delegate
            {
                if (!Alive(p) || tick > 24) return;
                try { Function.Call("SET_CURRENT_CHAR_WEAPON", p, PistolWeaponId, true); }
                catch (Exception ex) { LogOnce("pistolenf", "Re-equip failed: " + ex.Message); }
                if (tick % 4 == 1)
                {
                    try { Function.Call("TASK_SHOOT_AT_CHAR", p, Player.Character, 6000, 5); }
                    catch (Exception ex) { LogOnce("pistolshoot", "TASK_SHOOT_AT_CHAR failed: " + ex.Message); }
                    Log("Pistol ped: shooting task re-issued (tick " + tick + ")");
                }
                PistolEnforce(p, tick + 1);
            });
        }

        void ArmWithPistol(Ped p)
        {
            if (!Alive(p)) return;
            try
            {
                Function.Call("GIVE_WEAPON_TO_CHAR", p, PistolWeaponId, PistolAmmo, false);
                Function.Call("SET_CURRENT_CHAR_WEAPON", p, PistolWeaponId, true);
            }
            catch (Exception ex) { LogOnce("pistol", "Giving pistol failed: " + ex.Message); }
        }

        void RunAway(Ped p)
        {
            if (!Alive(p)) return;
            GetState(p, Now()).HoldUntil = 0;
            BlockEvents(p, false);
            p.Task.ClearAll();
            p.Task.FleeFromChar(Player.Character);
        }

        void WalkAway(Ped p)
        {
            if (!Alive(p)) return;
            GetState(p, Now()).HoldUntil = 0;
            BlockEvents(p, false);
            p.Task.ClearAll();
            p.Task.WanderAround();
        }

        void DropCashPickup(Ped p, int cash)
        {
            try
            {
                Vector3 pos = p.GetOffsetPosition(new Vector3(0.0f, 0.6f, 0.0f));
                float z = pos.Z - CashFallbackDrop;
                try
                {
                    Pointer gz = new Pointer(typeof(float));
                    Function.Call("GET_GROUND_Z_FOR_3D_COORD", pos.X, pos.Y, pos.Z + 0.5f, gz);
                    float found = Convert.ToSingle(gz.Value);
                    if (found > pos.Z - 3.0f && found < pos.Z + 1.0f) z = found + CashGroundLift;
                }
                catch (Exception ex) { LogOnce("groundz", "Ground height lookup failed, using fallback: " + ex.Message); }
                Pointer pickup = new Pointer(typeof(int));
                Function.Call("CREATE_MONEY_PICKUP", pos.X, pos.Y, z, cash, false, pickup);
                Log("Cash pickup dropped: $" + cash);
            }
            catch (Exception ex)
            {
                LogOnce("moneypickup", "CREATE_MONEY_PICKUP failed, adding cash directly: " + ex.Message);
                Player.Money += cash;
                Game.DisplayText("+$" + cash, 3000);
            }
        }

        void PlayAnimWhenLoaded(Ped p, string set, string name, int waited)
        {
            if (!Alive(p)) return;
            try
            {
                Function.Call("REQUEST_ANIMS", set);
                if (Function.Call<bool>("HAVE_ANIMS_LOADED", set))
                {
                    Function.Call("TASK_PLAY_ANIM", p, name, set, 8.0f, 0, 0, 0, 0, -1);
                    return;
                }
            }
            catch (Exception ex)
            {
                LogOnce("anim" + name, "Animation " + set + "/" + name + " failed: " + ex.Message);
                return;
            }
            if (waited > 2000)
            {
                LogOnce("animload" + name, "Animation set '" + set + "' did not load, skipping " + name);
                return;
            }
            Later(100, delegate { PlayAnimWhenLoaded(p, set, name, waited + 100); });
        }

        void RemoveWad(GTA.Object[] holder)
        {
            try
            {
                if (holder[0] != null)
                {
                    holder[0].Delete();
                    holder[0] = null;
                }
            }
            catch (Exception ex) { LogOnce("wadremove", "Removing the cash prop failed: " + ex.Message); }
        }

        void WalletSequence(Ped p, int cash)
        {
            WalletSequence(p, cash, false);
        }

        void WalletSequence(Ped p, int cash, bool pusherDealer)
        {
            if (!Alive(p)) return;
            PedState hs = GetState(p, Now());
            hs.HoldUntil = 0;
            BlockEvents(p, true);
            try { p.Task.ClearAll(); } catch (Exception) { }
            try { Function.Call("TASK_STAND_STILL", p, 3000); } catch (Exception) { }
            Function.Call("REQUEST_ANIMS", CashDropSet);

            GTA.Object[] wad = new GTA.Object[1];
            Later(WadAttachDelayMs, delegate
            {
                if (!Alive(p)) return;
                try
                {
                    wad[0] = World.CreateObject(new Model(CashModelName), p.Position);
                    wad[0].AttachToPed(p, Bone.RightHand, new Vector3(WadOffsetX, WadOffsetY, WadOffsetZ), new Vector3(WadRotX, WadRotY, WadRotZ));
                    Log("Cash prop attached to hand");
                }
                catch (Exception ex) { LogOnce("wadattach", "Cash prop could not be attached: " + ex.Message); }
            });

            Job0 onDropEnded = delegate
            {
                RemoveWad(wad);
                if (!Alive(p)) return;
                RunAway(p);
                Scream(p);
            };
            Job0 onDropStarted = delegate
            {
                Later(CashSpawnInDropMs, delegate
                {
                    RemoveWad(wad);
                    if (!Alive(p)) return;
                    if (pusherDealer) PusherDealerDrop(p);
                    else DropCashPickup(p, cash);
                });
            };
            Job0 startSequence = delegate
            {
                if (!Alive(p)) { RemoveWad(wad); return; }
                bool ok = false;
                try
                {
                    Pointer seq = new Pointer(typeof(int));
                    Function.Call("OPEN_SEQUENCE_TASK", seq);
                    Function.Call("TASK_PLAY_ANIM", 0, WalletOutAnim, WalletOutSet, 8.0f, 0, 0, 0, 0, -1);
                    Function.Call("TASK_PLAY_ANIM", 0, CashDropAnim, CashDropSet, 8.0f, 0, 0, 0, 0, -1);
                    Function.Call("TASK_STAND_STILL", 0, 4000);
                    int seqId = Convert.ToInt32(seq.Value);
                    Function.Call("CLOSE_SEQUENCE_TASK", seqId);
                    Function.Call("TASK_PERFORM_SEQUENCE", p, seqId);
                    Function.Call("CLEAR_SEQUENCE_TASK", seq);
                    ok = true;
                    Log("Wallet animations started as one task sequence");
                }
                catch (Exception ex) { LogOnce("seqfail", "Task sequence failed, playing the animations one by one: " + ex.Message); }
                if (ok)
                {
                    WatchAnimStart(p, CashDropSet, CashDropAnim, 0, WalletOutMs + 3000, onDropStarted);
                    WatchAnim(p, CashDropSet, CashDropAnim, 0, false, WalletOutMs + CashDropMs + 4500, onDropEnded);
                }
                else
                {
                    PlayAnimThen(p, WalletOutSet, WalletOutAnim, WalletOutMs + 1500, delegate
                    {
                        if (!Alive(p)) { RemoveWad(wad); return; }
                        onDropStarted();
                        PlayAnimThen(p, CashDropSet, CashDropAnim, CashDropMs + 1500, onDropEnded);
                    });
                }
            };
            WaitSetsLoaded(p, 0, startSequence);
        }

        void WaitSetsLoaded(Ped p, int waited, Job0 next)
        {
            if (!Alive(p)) { next(); return; }
            bool loaded = false;
            try
            {
                Function.Call("REQUEST_ANIMS", WalletOutSet);
                Function.Call("REQUEST_ANIMS", CashDropSet);
                loaded = Function.Call<bool>("HAVE_ANIMS_LOADED", WalletOutSet) && Function.Call<bool>("HAVE_ANIMS_LOADED", CashDropSet);
            }
            catch (Exception ex) { LogOnce("setsload", "Animation request failed: " + ex.Message); }
            if (loaded || waited >= 2500) { next(); return; }
            Later(100, delegate { WaitSetsLoaded(p, waited + 100, next); });
        }

        void WatchAnimStart(Ped p, string set, string name, int elapsed, int maxMs, Job0 onStart)
        {
            Later(50, delegate
            {
                bool playing = false;
                if (Alive(p))
                {
                    try { playing = Function.Call<bool>("IS_CHAR_PLAYING_ANIM", p, set, name); }
                    catch (Exception) { }
                }
                int nowElapsed = elapsed + 50;
                if (!Alive(p) || playing || nowElapsed >= maxMs)
                {
                    onStart();
                    return;
                }
                WatchAnimStart(p, set, name, nowElapsed, maxMs, onStart);
            });
        }

        void PlayAnimThen(Ped p, string set, string name, int maxMs, Job0 next)
        {
            PlayAnimWhenLoaded(p, set, name, 0);
            WatchAnim(p, set, name, 0, false, maxMs, next);
        }

        void WatchAnim(Ped p, string set, string name, int elapsed, bool seen, int maxMs, Job0 next)
        {
            Later(50, delegate
            {
                bool playing = false;
                if (Alive(p))
                {
                    try { playing = Function.Call<bool>("IS_CHAR_PLAYING_ANIM", p, set, name); }
                    catch (Exception ex) { LogOnce("isplaying", "IS_CHAR_PLAYING_ANIM failed: " + ex.Message); }
                }
                bool nowSeen = seen || playing;
                int nowElapsed = elapsed + 50;
                if (!Alive(p) || (nowSeen && !playing) || nowElapsed >= maxMs)
                {
                    if (next != null) next();
                    return;
                }
                WatchAnim(p, set, name, nowElapsed, nowSeen, maxMs, next);
            });
        }

        void PlayDropAnim(Ped p)
        {
            if (DropAnimSet.Length == 0 || DropAnimName.Length == 0) return;
            Function.Call("REQUEST_ANIMS", DropAnimSet);
            WaitAndPlayAnim(p, 0);
        }

        void WaitAndPlayAnim(Ped p, int waited)
        {
            if (!Alive(p)) return;
            if (Function.Call<bool>("HAVE_ANIMS_LOADED", DropAnimSet))
            {
                Function.Call("TASK_PLAY_ANIM", p, DropAnimName, DropAnimSet, 8.0f, 0, 0, 0, 0, -1);
                return;
            }
            if (waited > 1500) return;
            Later(100, delegate { WaitAndPlayAnim(p, waited + 100); });
        }

        Dictionary<int, string> modelLabels = new Dictionary<int, string>();
        List<string> factionKeys = new List<string>();
        List<string> factionLabels = new List<string>();

        void LoadFactions(string root)
        {
            factionKeys.Clear();
            factionLabels.Clear();
            modelLabels.Clear();
            string path = Path.Combine(root, FactionFileName);
            try
            {
                if (File.Exists(path))
                {
                    foreach (string raw in File.ReadAllLines(path))
                    {
                        string line = raw.Trim();
                        if (line.Length == 0 || line.StartsWith("#") || line.StartsWith("//")) continue;
                        int eq = line.IndexOf('=');
                        if (eq <= 0) continue;
                        string key = line.Substring(0, eq).Trim();
                        string label = line.Substring(eq + 1).Trim();
                        if (key.Length == 0 || label.Length == 0) continue;
                        if (key.ToLower().StartsWith("model:"))
                        {
                            string mname = key.Substring(6).Trim();
                            if (mname.Length > 0)
                            {
                                modelLabels[ModelHash(mname)] = label;
                                factionLabels.Add(label);
                                factionKeys.Add("\u0001MODEL");
                            }
                            continue;
                        }
                        factionKeys.Add(NormalizeKey(key));
                        factionLabels.Add(label);
                    }
                    Log("Faction names: " + (factionKeys.Count - modelLabels.Count) + " ped type rule(s) and " + modelLabels.Count + " model rule(s) loaded from " + path);
                    return;
                }
            }
            catch (Exception ex) { Log("Faction file could not be read: " + ex.Message); }
            factionKeys.Add("COP"); factionLabels.Add("Polic\u00eda");
            factionKeys.Add("POLICE"); factionLabels.Add("Polic\u00eda");
            factionKeys.Add("PROSTITUTE"); factionLabels.Add("Prostituta");
            Log("No factions.txt found at " + path + ", using the built-in defaults");
        }

        // Traduccion al espanol de las opciones del menu
        static string ES(string s)
        {
            switch (s)
            {
                case "Rob": return "Robar";
                case "Greet": return "Saludar";
                case "Taunt": return "Provocar";
                case "Sell": return "Vender";
                case "Buy": return "Comprar";
                default: return s;
            }
        }

        static string NormalizeKey(string s)
        {
            return s.Replace("_", "").Replace(" ", "").ToUpper();
        }

        static int ModelHash(string name)
        {
            string n = name.ToLower();
            uint h = 0;
            for (int i = 0; i < n.Length; i++)
            {
                h += (uint)n[i];
                h += (h << 10);
                h ^= (h >> 6);
            }
            h += (h << 3);
            h ^= (h >> 11);
            h += (h << 15);
            return unchecked((int)h);
        }

        System.Reflection.PropertyInfo modelProp;
        System.Reflection.PropertyInfo modelHashProp;
        bool modelSearched;

        bool TryModelHash(Ped p, out int hash)
        {
            hash = 0;
            try
            {
                if (!modelSearched)
                {
                    modelSearched = true;
                    modelProp = p.GetType().GetProperty("Model");
                    if (modelProp != null) modelHashProp = modelProp.PropertyType.GetProperty("Hash");
                    if (modelProp == null || modelHashProp == null) Log("Model lookup unavailable on this Ped (model rules in factions.txt will be ignored)");
                }
                if (modelProp == null || modelHashProp == null) return false;
                object m = modelProp.GetValue(p, null);
                if (m == null) return false;
                object h = modelHashProp.GetValue(m, null);
                if (h == null) return false;
                hash = unchecked((int)Convert.ToInt64(h));
                return true;
            }
            catch (Exception) { return false; }
        }

        string PedTypeName(Ped p)
        {
            try
            {
                if (!pedTypeSearched)
                {
                    pedTypeSearched = true;
                    pedTypeProp = p.GetType().GetProperty("PedType");
                }
                if (pedTypeProp == null) return "";
                object v = pedTypeProp.GetValue(p, null);
                return (v == null) ? "" : v.ToString();
            }
            catch (Exception) { return ""; }
        }

        string LabelFor(Ped p, PedState st)
        {
            if (st.Label != null) return st.Label;
            string type = PedTypeName(p);
            string u = NormalizeKey(type);
            string label = DefaultNameLabel;
            string how = "no rule";
            int hash;
            bool haveHash = TryModelHash(p, out hash);
            if (haveHash && modelLabels.ContainsKey(hash))
            {
                label = modelLabels[hash];
                how = "model rule";
            }
            if (label == DefaultNameLabel)
            {
                for (int i = 0; i < factionKeys.Count; i++)
                {
                    if (factionKeys[i] == "\u0001MODEL") continue;
                    if (u == factionKeys[i]) { label = factionLabels[i]; how = "type rule"; break; }
                }
            }
            if (label == DefaultNameLabel)
            {
                for (int i = 0; i < factionKeys.Count; i++)
                {
                    if (factionKeys[i] == "\u0001MODEL") continue;
                    if (u.Contains(factionKeys[i])) { label = factionLabels[i]; how = "type rule"; break; }
                }
            }
            st.Label = label;
            LogOnce("lock_" + type + "_" + hash, "Locked on ped type '" + type + "', model hash " + (haveHash ? hash.ToString() : "unknown") + " -> menu name '" + label + "' (" + how + ")");
            return label;
        }

        System.Reflection.PropertyInfo pedTypeProp;
        bool pedTypeSearched;

        bool IsCop(Ped p)
        {
            try
            {
                if (!pedTypeSearched)
                {
                    pedTypeSearched = true;
                    pedTypeProp = p.GetType().GetProperty("PedType");
                    if (pedTypeProp == null) Log("Police detection unavailable: Ped has no PedType property");
                    else Log("Police detection: using Ped.PedType (" + pedTypeProp.PropertyType.Name + ")");
                }
                if (pedTypeProp == null) return false;

                object v = pedTypeProp.GetValue(p, null);
                string t = (v == null) ? "" : v.ToString();
                LogOnce("pedtype_" + t, "Ped type seen near a robbery: '" + t + "'");
                string u = t.ToUpper();
                return u.Contains("COP") || u.Contains("POLICE");
            }
            catch (Exception) { return false; }
        }

        void GiveWantedStars(int stars)
        {
            try
            {
                object pl = Player;
                System.Reflection.PropertyInfo pi = pl.GetType().GetProperty("WantedLevel");
                if (pi != null && pi.CanRead && pi.CanWrite)
                {
                    int current = Convert.ToInt32(pi.GetValue(pl, null));
                    if (current < stars) pi.SetValue(pl, Convert.ChangeType(stars, pi.PropertyType), null);
                    Log("Wanted level set through Player.WantedLevel (was " + current + ", now at least " + stars + ")");
                    return;
                }
            }
            catch (Exception ex) { Log("Player.WantedLevel failed: " + ex.Message); }

            try
            {
                int idx = Function.Call<int>("GET_PLAYER_ID");
                Function.Call("ALTER_WANTED_LEVEL_NO_DROP", idx, stars);
                Function.Call("APPLY_WANTED_LEVEL_CHANGE_NOW", idx);
                Log("Wanted level set through ALTER_WANTED_LEVEL_NO_DROP");
            }
            catch (Exception ex) { Log("Could not set the wanted level: " + ex.Message); }
        }

        void RobberyWitnessed(Ped victim)
        {
            try
            {
                Ped player = Player.Character;
                Vector3 pp = player.Position;
                float search = Math.Max(BystanderFleeRadius, PoliceSightRadius) + 1.0f;
                Ped[] peds = World.GetPeds(pp, search);

                int fled = 0;
                int copsSeen = 0;
                int copsClose = 0;

                foreach (Ped p in peds)
                {
                    if (!Game.Exists(p)) continue;
                    if (SamePed(p, player) || SamePed(p, victim)) continue;
                    if (!p.isAliveAndWell) continue;

                    Vector3 pos = p.Position;
                    float dx = pos.X - pp.X;
                    float dy = pos.Y - pp.Y;
                    float dz = pos.Z - pp.Z;
                    float dist = (float)Math.Sqrt(dx * dx + dy * dy + dz * dz);

                    if (IsCop(p))
                    {
                        copsSeen++;
                        if (dist <= PoliceSightRadius) copsClose++;
                        continue;
                    }

                    if (dist <= BystanderFleeRadius && !p.isInVehicle())
                    {
                        Ped runner = p;
                        Later(rng.Next(150, 900), delegate { RunAway(runner); });
                        fled++;
                    }
                }

                Log("Robbery witnessed: " + fled + " bystander(s) running, police nearby=" + copsSeen + ", police within " + PoliceSightRadius + " m=" + copsClose);
                if (copsClose > 0) GiveWantedStars(PoliceWantedStars);
            }
            catch (Exception ex) { Log("RobberyWitnessed failed: " + ex.Message); }
        }

        void DoGreet(Ped ped, PedState st, long now)
        {
            bool finalGreet = st.GreetCount >= 1;
            string file = PickLine(finalGreet ? greetEndBank : greetBeginBank);
            if (file == null)
            {
                Game.DisplayText("No " + (finalGreet ? "GREETEND" : "GREETBEGIN") + " audio found in " + dialogueRoot + "\\Greet", 4000);
                return;
            }

            int len = PlayVoice(file);
            if (len == 0) return;
            st.GreetCount++;
            if (st.GreetCount >= GreetsBeforeLock) st.GreetLockUntil = now + LockoutMs;
            busyUntil = now + len + 600;

            FacePlayer(ped, len + 1800);
            Later(len + 150, delegate { SayFor(ped, file, finalGreet ? "farewell" : "hello"); });
        }

        void DoTaunt(Ped ped, PedState st, long now)
        {
            string file = PickLine(tauntBank);
            if (file == null)
            {
                Game.DisplayText("No taunt audio found in " + dialogueRoot, 4000);
                return;
            }

            int len = PlayVoice(file);
            st.TauntCount++;
            busyUntil = now + len + 600;

            FacePlayer(ped, len + 1800);
            Later(len + 150, delegate { SayFor(ped, file, "insult"); });

            if (st.TauntCount >= TauntsBeforeLock)
            {
                st.TauntLockUntil = now + LockoutMs;
                st.DisengagedUntil = now + len + DisengagedMs;
                bool aggro = rng.Next(100) < TauntAggroPct;
                Later(len + 1400, delegate
                {
                    if (aggro) MakeHostile(ped);
                    else WalkAway(ped);
                });
            }
        }

        void DoRob(Ped ped, PedState st, long now)
        {
            string file = PickLine(robBank);
            if (file == null)
            {
                Game.DisplayText("No rob audio found in " + dialogueRoot, 4000);
                return;
            }

            int len = PlayVoice(file);
            st.Robbed = true;
            st.DisengagedUntil = now + len + DisengagedMs;
            busyUntil = now + len + 600;

            RobberyWitnessed(ped);

            int roll = rng.Next(100);
            int outcome;
            bool female = IsFemale(ped);
            if (female)
            {
                outcome = roll < FemaleRobComplyPct ? 0 : 2;
            }
            else
            {
                if (roll < MaleRobComplyPct) outcome = 0;
                else if (roll < MaleRobComplyPct + MaleRobMeleePct) outcome = 1;
                else if (roll < MaleRobComplyPct + MaleRobMeleePct + MaleRobPistolPct) outcome = 3;
                else outcome = 2;
            }
            Log("Rob outcome: " + (female ? "female" : "male") + " roll=" + roll + " outcome=" + outcome);

            HoldHandsUp(ped, len + 9000);

            if (outcome == 0)
            {
                int seqMs = WalletStartDelayMs + WalletOutMs + CashDropMs;
                busyUntil = now + len + seqMs + 400 + RobAfterExtraDelayMs;
                bool playAfterLine = rng.Next(100) < RobAfterLinePct;
                int cash = female ? rng.Next(FemaleMinCash, FemaleMaxCash + 1) : rng.Next(MaleMinCash, MaleMaxCash + 1);

                Later(len + 700, delegate { SayFor(ped, file, "demand"); });
                Later(len + WalletStartDelayMs, delegate { WalletSequence(ped, cash); });
                if (playAfterLine)
                {
                    Later(len + seqMs + RobAfterExtraDelayMs, delegate
                    {
                        string after = PickLine(robAfterBank);
                        if (after != null) PlayVoice(after);
                    });
                }
            }
            else if (outcome == 1)
            {
                Later(len + 200, delegate { SayFor(ped, file, "insult"); });
                Later(len + 900, delegate { MakeHostile(ped); });
            }
            else if (outcome == 3)
            {
                Later(len + 200, delegate { SayFor(ped, file, "insult"); });
                Later(1000, delegate { PistolAttack(ped); });
            }
            else
            {
                Later(len + 200, delegate { Scream(ped); });
                Later(len + 400, delegate { RunAway(ped); });
            }
        }

        Dictionary<string, bool> loggedOnce = new Dictionary<string, bool>();

        void LogOnce(string key, string msg)
        {
            if (loggedOnce.ContainsKey(key)) return;
            loggedOnce[key] = true;
            Log(msg);
        }

        bool SafeBool0(string name)
        {
            try { return Function.Call<bool>(name); }
            catch (Exception ex) { LogOnce(name, name + " failed: " + ex.Message); return false; }
        }

        bool SafeBool(string name, Parameter a)
        {
            try { return Function.Call<bool>(name, a); }
            catch (Exception ex) { LogOnce(name, name + " failed: " + ex.Message); return false; }
        }

        bool SafeBool(string name, Parameter a, Parameter b)
        {
            try { return Function.Call<bool>(name, a, b); }
            catch (Exception ex) { LogOnce(name, name + " failed: " + ex.Message); return false; }
        }

        bool SafeBool(string name, Parameter a, Parameter b, Parameter c)
        {
            try { return Function.Call<bool>(name, a, b, c); }
            catch (Exception ex) { LogOnce(name, name + " failed: " + ex.Message); return false; }
        }

        void SafeCall(string name, Parameter a)
        {
            try { Function.Call(name, a); }
            catch (Exception ex) { LogOnce(name, name + " failed: " + ex.Message); }
        }

        bool missionCached;
        bool missionLogged;
        bool controlCached = true;
        long nextStateCheck;

        bool BlockedByGameState(int playerIdx)
        {
            long n = Now();
            if (n >= nextStateCheck)
            {
                nextStateCheck = n + 250;

                bool m = false;
                if (BlockDuringMissions) m = SafeBool0("GET_MISSION_FLAG");
                if (m != missionCached || !missionLogged) { missionCached = m; missionLogged = true; Log("Mission flag = " + m); }

                bool ctl = true;
                try { ctl = Function.Call<bool>("IS_PLAYER_CONTROL_ON", playerIdx); }
                catch (Exception ex) { LogOnce("ctl", "IS_PLAYER_CONTROL_ON failed: " + ex.Message); }
                if (ctl != controlCached) { controlCached = ctl; Log("Player control = " + ctl); }
            }
            return missionCached || !controlCached;
        }

        System.Reflection.PropertyInfo healthProp;
        bool healthSearched;
        Dictionary<int, int> lastHealthByHandle = new Dictionary<int, int>();
        long playerHurtUntil;
        int lastPlayerHealth = -1;

        int HealthValue(Ped p)
        {
            try
            {
                if (!healthSearched)
                {
                    healthSearched = true;
                    healthProp = p.GetType().GetProperty("Health");
                    if (healthProp == null) Log("Hostile detection unavailable: Ped has no Health property");
                }
                if (healthProp == null) return -1;
                return Convert.ToInt32(healthProp.GetValue(p, null));
            }
            catch (Exception) { return -1; }
        }

        long lastAggroScan;
        long nextAggroScan;
        long playerAttackUntil;

        void ScanAggro(Ped player, Ped[] peds, long now, bool playerAttacking)
        {
            if (now - lastAggroScan > 1500)
            {
                lastHealthByHandle.Clear();
                lastPlayerHealth = -1;
            }
            lastAggroScan = now;

            Vector3 pp = player.Position;
            bool playerHurt = false;
            int ph = HealthValue(player);
            if (ph >= 0)
            {
                if (lastPlayerHealth >= 0 && ph < lastPlayerHealth) playerHurt = true;
                lastPlayerHealth = ph;
            }

            if (lastHealthByHandle.Count > 300) lastHealthByHandle.Clear();

            foreach (Ped p in peds)
            {
                if (!Game.Exists(p)) continue;
                if (SamePed(p, player)) continue;
                if (!p.isAliveAndWell) continue;

                int h = HealthValue(p);
                if (h < 0) continue;
                int key = HandleOf(p);
                if (key == int.MinValue) continue;

                int prev;
                if (lastHealthByHandle.TryGetValue(key, out prev) && h < prev)
                {
                    Vector3 pos = p.Position;
                    float dx = pos.X - pp.X;
                    float dy = pos.Y - pp.Y;
                    float d2 = dx * dx + dy * dy;
                    bool hit = false;
                    if (playerAttacking && d2 <= HurtByPlayerRadius * HurtByPlayerRadius) hit = true;
                    if (playerHurt && d2 <= HurtPlayerRadius * HurtPlayerRadius) hit = true;
                    if (hit)
                    {
                        GetState(p, now).AggroUntil = now + AggroHoldMs;
                        Log("Ped marked hostile (hurt near an attack on or by the player)");
                    }
                }
                lastHealthByHandle[key] = h;
            }
        }

        bool HasGunInHand(Ped p)
        {
            try
            {
                Pointer w = new Pointer(typeof(int));
                Function.Call("GET_CURRENT_CHAR_WEAPON", p, w);
                int id = Convert.ToInt32(w.Value);
                LogOnce("weaponid_" + id, "Weapon id seen in a target's hand: " + id + (id >= FirstArmedWeaponId ? " (counts as armed)" : " (counts as unarmed)"));
                return id >= FirstArmedWeaponId;
            }
            catch (Exception ex)
            {
                LogOnce("curweapon", "GET_CURRENT_CHAR_WEAPON failed, assuming unarmed: " + ex.Message);
                return false;
            }
        }

        void ReleaseHoldsIfFiring(bool firing, long now)
        {
            if (!firing) return;
            bool any = false;
            foreach (PedEntry e in entries)
            {
                if (e.State.HoldUntil > now) { any = true; break; }
            }
            if (!any) return;

            foreach (PedEntry e in entries)
            {
                if (e.State.HoldUntil > now)
                {
                    e.State.HoldUntil = 0;
                    if (Alive(e.Ped))
                    {
                        BlockEvents(e.Ped, false);
                        try { e.Ped.Task.ClearAll(); }
                        catch (Exception) { }
                    }
                }
            }
            Log("Fire input: gunpoint holds released");
        }

        System.Reflection.PropertyInfo wantedProp;
        bool wantedSearched;

        bool WantedNow()
        {
            try
            {
                object pl = Player;
                if (!wantedSearched)
                {
                    wantedSearched = true;
                    wantedProp = pl.GetType().GetProperty("WantedLevel");
                    if (wantedProp == null) Log("Wanted-level check unavailable: Player has no WantedLevel property");
                }
                if (wantedProp == null) return false;
                return Convert.ToInt32(wantedProp.GetValue(pl, null)) > 0;
            }
            catch (Exception) { return false; }
