        bool AnyAggro(int playerIdx, long now)
        {
            if (playerHurtUntil > now) return true;
            if (WantedNow()) return true;
            foreach (PedEntry e in entries)
            {
                if (e.State.AggroUntil > now && Alive(e.Ped)) return true;
            }
            return false;
        }

        Ped FindTarget(Ped player, int playerIdx, Ped[] peds, out int mode)
        {
            mode = 0;
            Ped locked = null;
            Vector3 pp = player.Position;

            foreach (Ped p in peds)
            {
                if (!Game.Exists(p)) continue;
                if (SamePed(p, player)) continue;
                if (!p.isAliveAndWell) continue;
                if (p.isInVehicle()) continue;

                Vector3 pos = p.Position;
                float dx = pos.X - pp.X;
                float dy = pos.Y - pp.Y;
                if (dx * dx + dy * dy > LockOnSearchRadius * LockOnSearchRadius) continue;

                if (SafeBool("IS_PLAYER_FREE_AIMING_AT_CHAR", playerIdx, p))
                {
                    mode = 2;
                    return p;
                }
                if (locked == null && SafeBool("IS_PLAYER_TARGETTING_CHAR", playerIdx, p)) locked = p;
            }

            if (locked != null) mode = 1;
            return locked;
        }

        #region Pusher compatibility
        // Talks to Pusher.cs through AppDomain data. Does nothing when Pusher is not installed.
        const bool PusherCompat = true;
        const string PusherDealerLabel = "Traficante";

        static object PusherData(string key) { return AppDomain.CurrentDomain.GetData(key); }

        void PusherAnnounce()
        {
            try { AppDomain.CurrentDomain.SetData("GreetTauntRob.PusherCompat", PusherCompat); }
            catch (Exception ex) { Log("Pusher announce failed: " + ex.Message); }
        }

        // Pusher counts as installed only while it is actually running (it stamps
        // Pusher.Alive every frame) and has its GreetTauntRob link switched on.
        // If Pusher is missing, failed to compile or stopped, everything below
        // returns false and this script behaves exactly as it does on its own.
        bool PusherInstalled()
        {
            if (!PusherCompat) return false;
            try
            {
                if (PusherData("Pusher.Version") == null) return false;
                if (!true.Equals(PusherData("Pusher.GtrLink"))) return false;
                object a = PusherData("Pusher.Alive");
                if (!(a is int)) return false;
                int age = Game.GameTime - (int)a;
                return age > -3000 && age < 3000;
            }
            catch { return false; }
        }

        // tells Pusher this script is running, every frame
        void PusherHeartbeat()
        {
            try { AppDomain.CurrentDomain.SetData("GreetTauntRob.Alive", Game.GameTime); }
            catch { }
        }

        // a Pusher menu or scene (deal, robbery, police search) is running
        bool PusherBusy() { return PusherInstalled() && true.Equals(PusherData("Pusher.Busy")); }

        bool PusherIsDealer(Ped p)
        {
            if (!PusherInstalled() || p == null) return false;
            try
            {
                Predicate<Ped> f = PusherData("Pusher.IsDealer") as Predicate<Ped>;
                return f != null && f(p);
            }
            catch (Exception ex) { LogOnce("pusherdealer", "Pusher.IsDealer failed: " + ex.Message); return false; }
        }

        bool PusherIsBuyer(Ped p)
        {
            if (!PusherInstalled() || p == null) return false;
            try
            {
                Predicate<Ped> f = PusherData("Pusher.IsBuyer") as Predicate<Ped>;
                return f != null && f(p);
            }
            catch (Exception ex) { LogOnce("pusherbuyer", "Pusher.IsBuyer failed: " + ex.Message); return false; }
        }

        void PusherCall(string key, Ped p)
        {
            try
            {
                Action<Ped> f = PusherData(key) as Action<Ped>;
                if (f != null) f(p);
                else LogOnce("pmiss" + key, key + " not found - is Pusher.cs up to date?");
            }
            catch (Exception ex) { Log(key + " failed: " + ex.Message); }
        }

        void PusherSell(Ped p, string label)
        {
            try
            {
                Action<Ped, string> f = PusherData("Pusher.OpenSellAs") as Action<Ped, string>;
                if (f != null) f(p, label);
            }
            catch (Exception ex) { Log("Pusher.OpenSellAs failed: " + ex.Message); }
        }

        void PusherOpenDealer(Ped p) { PusherCall("Pusher.OpenDealer", p); }
        void PusherDealerDrop(Ped p) { PusherCall("Pusher.DealerDrop", p); }

