        void DrawDealerMenu()
        {
            float y = RightTop + 2.0f * RowStep;
            DrawRow(RightEdge, y, "Buy", true, IconKind.RT);
            float divY = y + RowStep * 0.62f;
            Rect(RightEdge - 0.075f, divY, 0.15f, 0.0016f, 255, 255, 255, 190);
            float nameY = y + RowStep * 1.22f;
            float colW = ColWidth();
            float nameRight = RightEdge - colW - 0.008f;
            if (!AddTextSprite("name:" + PusherDealerLabel, nameRight, nameY, NameTextHeight))
                DrawText(PusherDealerLabel, nameRight, nameY - 0.0717f * NameScale + TextYOffset, NameScale, 255, 255, 255, 255, true, false);
            AddIcon(IconKind.LT, true, rightEdgeLt(colW), nameY);
        }

