        // Pusher rolls it: true = he gives up, false = he pulls a gun (Pusher makes him fight)
        bool PusherRobDealer(Ped p)
        {
            try
            {
                Func<Ped, bool> f = PusherData("Pusher.RobDealer") as Func<Ped, bool>;
                if (f != null) return f(p);
            }
            catch (Exception ex) { Log("Pusher.RobDealer failed: " + ex.Message); return true; }
            PusherCall("Pusher.RobDealerStart", p);       // older Pusher: he always gives up
            return true;
        }

        // gunpoint robbery of a dealer: half the time hands up, wallet, drops his cash and stash; otherwise he shoots
        void DoRobDealer(Ped ped, PedState st, long now)
        {
            string file = PickLine(robBank);
            int len = file != null ? PlayVoice(file) : 0;
            st.Robbed = true;
            st.DisengagedUntil = now + len + DisengagedMs;
            if (!PusherRobDealer(ped))
            {
                busyUntil = now + 1000;
                RobberyWitnessed(ped);
                Log("Dealer robbed at gunpoint: he fights back");
                return;
            }
            int seqMs = WalletStartDelayMs + WalletOutMs + CashDropMs;
            busyUntil = now + len + seqMs + 400 + RobAfterExtraDelayMs;
            RobberyWitnessed(ped);
            HoldHandsUp(ped, len + 9000);
            Log("Dealer robbed at gunpoint");

            bool playAfterLine = rng.Next(100) < RobAfterLinePct;
            if (file != null) Later(len + 700, delegate { SayFor(ped, file, "demand"); });
            Later(len + WalletStartDelayMs, delegate { WalletSequence(ped, 0, true); });
            if (playAfterLine)
            {
                Later(len + seqMs + RobAfterExtraDelayMs, delegate
                {
                    string after = PickLine(robAfterBank);
                    if (after != null) PlayVoice(after);
                });
            }
        }
