        float aspect = 16.0f / 9.0f;
        int resW = 1920;
        int resH = 1080;

        enum IconKind { LB, LT, DpadLeft, DpadRight, RB, RT }

        class IconCmd
        {
            public Texture Tex;
            public float Aspect;
            public float Cx;
            public float Cy;
            public float H;
        }

        List<IconCmd> iconCmds = new List<IconCmd>();
        List<IconCmd> pending = new List<IconCmd>();
        bool spritesBroken;

        Texture texLb, texLbOff, texLt, texDl, texDlOff, texDr, texDrOff, texRb, texRbOff, texRt, texRtOff;

        Texture LoadTex(string b64)
        {
            return new Texture(Convert.FromBase64String(b64));
        }

        void LoadIcons()
        {
            try
            {
                texLb = LoadTex(IconLb);
                texLbOff = LoadTex(IconLbOff);
                texLt = LoadTex(IconLt);
                texDl = LoadTex(IconDl);
                texDlOff = LoadTex(IconDlOff);
                texDr = LoadTex(IconDr);
                texDrOff = LoadTex(IconDrOff);
                texRb = LoadTex(IconRb);
                texRbOff = LoadTex(IconRbOff);
                texRt = LoadTex(IconRt);
                texRtOff = LoadTex(IconRtOff);
                Log("Icon textures loaded");
            }
            catch (Exception ex)
            {
                texLb = null; texLbOff = null; texLt = null;
                texDl = null; texDlOff = null; texDr = null; texDrOff = null;
                texRb = null; texRbOff = null; texRt = null; texRtOff = null;
                Log("Icon load failed, using simple fallback icons: " + ex.Message);
            }
        }

        class TextTex
        {
            public Texture Tex;
            public float Aspect;
            public float CapCenter;
            public float PadRight;
        }

        Dictionary<string, TextTex> textTex = new Dictionary<string, TextTex>();
        bool customFontOk;
        System.Drawing.Text.PrivateFontCollection fontCollection;

        System.Drawing.FontStyle PickStyle(System.Drawing.FontFamily fam, bool wantBold)
        {
            if (wantBold && fam.IsStyleAvailable(System.Drawing.FontStyle.Bold)) return System.Drawing.FontStyle.Bold;
            if (fam.IsStyleAvailable(System.Drawing.FontStyle.Regular)) return System.Drawing.FontStyle.Regular;
            if (fam.IsStyleAvailable(System.Drawing.FontStyle.Bold)) return System.Drawing.FontStyle.Bold;
            return System.Drawing.FontStyle.Italic;
        }

        void LoadTextTextures(string gameDir)
        {
            try
            {
                string dir = Path.Combine(gameDir, FontFolder);
                if (!Directory.Exists(dir))
                {
                    Log("Font folder not found: " + dir + "  (using the game's built-in font)");
                    return;
                }

                string file = null;
                if (FontFileName.Length > 0)
                {
                    file = Path.Combine(dir, FontFileName);
                }
                else
                {
                    string[] all = Directory.GetFiles(dir);
                    Array.Sort(all);
                    foreach (string f in all)
                    {
                        string ext = Path.GetExtension(f).ToLower();
                        if (ext == ".ttf" || ext == ".otf") { file = f; break; }
                    }
                }
                if (file == null || !File.Exists(file))
                {
                    Log("No .ttf/.otf found in " + dir + "  (using the game's built-in font)");
                    return;
                }

                fontCollection = new System.Drawing.Text.PrivateFontCollection();
                fontCollection.AddFontFile(file);
                if (fontCollection.Families.Length == 0)
                {
                    Log("Font file could not be read: " + file);
                    return;
                }
                System.Drawing.FontFamily fam = fontCollection.Families[0];
                System.Drawing.FontStyle regular = PickStyle(fam, false);
                System.Drawing.FontStyle bold = PickStyle(fam, true);

                string[] labels = new string[] { "Rob", "Greet", "Taunt", "Sell", "Buy" };
                foreach (string label in labels)
                {
                    textTex[label] = RenderText(fam, regular, ES(label), 235, 235, 235, 255);
                    textTex[label + "_off"] = RenderText(fam, regular, ES(label), 125, 125, 125, 190);
                }
                textTex["name:" + DefaultNameLabel] = RenderText(fam, bold, DefaultNameLabel, 255, 255, 255, 255);
                textTex["name:" + PusherDealerLabel] = RenderText(fam, bold, PusherDealerLabel, 255, 255, 255, 255);
                foreach (string lab in factionLabels)
                {
                    if (!textTex.ContainsKey("name:" + lab)) textTex["name:" + lab] = RenderText(fam, bold, lab, 255, 255, 255, 255);
                }

                customFontOk = true;
                Log("Custom font loaded: " + fam.Name + " (" + Path.GetFileName(file) + ")");
            }
            catch (Exception ex)
            {
                customFontOk = false;
                textTex.Clear();
                Log("Custom font failed, using the built-in font: " + ex.Message);
            }
        }

        TextTex RenderText(System.Drawing.FontFamily fam, System.Drawing.FontStyle style, string text, int r, int g, int b, int a)
        {
            const float emPx = 64f;
            const int padX = 6;
            const int padY = 4;

            using (System.Drawing.Font font = new System.Drawing.Font(fam, emPx, style, System.Drawing.GraphicsUnit.Pixel))
            using (System.Drawing.StringFormat fmt = new System.Drawing.StringFormat(System.Drawing.StringFormat.GenericTypographic))
            {
                int lineH = (int)Math.Ceiling(font.GetHeight());

                float textW;
                using (System.Drawing.Bitmap tmp = new System.Drawing.Bitmap(1, 1))
                using (System.Drawing.Graphics mg = System.Drawing.Graphics.FromImage(tmp))
                {
                    textW = mg.MeasureString(text, font, 4096, fmt).Width;
                }

                int bmpW = (int)Math.Ceiling(textW) + padX * 2;
                int bmpH = lineH + padY * 2;

                using (System.Drawing.Bitmap bmp = new System.Drawing.Bitmap(bmpW, bmpH, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
                using (System.Drawing.Graphics gfx = System.Drawing.Graphics.FromImage(bmp))
                {
                    gfx.Clear(System.Drawing.Color.FromArgb(0, 0, 0, 0));
                    gfx.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;

                    using (System.Drawing.SolidBrush shadow = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(150, 0, 0, 0)))
                    using (System.Drawing.SolidBrush main = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(a, r, g, b)))
                    {
                        gfx.DrawString(text, font, shadow, padX + 2.5f, padY + 2.5f, fmt);
                        gfx.DrawString(text, font, main, padX, padY, fmt);
                    }

                    float capCenter = 0.5f;
                    using (System.Drawing.Bitmap hb = new System.Drawing.Bitmap(160, bmpH, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
                    using (System.Drawing.Graphics hg = System.Drawing.Graphics.FromImage(hb))
                    {
                        hg.Clear(System.Drawing.Color.FromArgb(0, 0, 0, 0));
                        hg.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
                        hg.DrawString("H", font, System.Drawing.Brushes.White, padX, padY, fmt);
                        int top = -1, bot = -1;
                        for (int row = 0; row < bmpH; row++)
                        {
                            bool hit = false;
                            for (int col = 0; col < 160; col++)
                            {
                                if (hb.GetPixel(col, row).A > 128) { hit = true; break; }
                            }
                            if (hit) { if (top < 0) top = row; bot = row; }
                        }
                        if (top >= 0) capCenter = ((top + bot + 1) * 0.5f) / (float)bmpH;
                    }

                    using (System.IO.MemoryStream ms = new System.IO.MemoryStream())
                    {
                        bmp.Save(ms, System.Drawing.Imaging.ImageFormat.Png);
                        TextTex t = new TextTex();
                        t.Tex = new Texture(ms.ToArray());
                        t.Aspect = (float)bmpW / (float)bmpH;
                        t.CapCenter = capCenter;
                        t.PadRight = (float)padX / (float)bmpH;
                        return t;
                    }
                }
            }
        }

        bool AddTextSprite(string key, float right, float cy, float heightNorm)
        {
            TextTex t;
            if (!customFontOk || spritesBroken || !textTex.TryGetValue(key, out t)) return false;

            float xScale = (float)resH / (float)resW;
            float wNorm = heightNorm * t.Aspect * xScale;
            IconCmd c = new IconCmd();
            c.Tex = t.Tex;
            c.Aspect = t.Aspect;
            c.H = heightNorm;
            c.Cx = right - wNorm * 0.5f + t.PadRight * heightNorm * xScale;
            c.Cy = cy + (0.5f - t.CapCenter) * heightNorm + TextYOffset;
            pending.Add(c);
            return true;
        }

        void UpdateResolution()
        {
            try
            {
                RECT r;
                if (GetClientRect(GetForegroundWindow(), out r))
                {
                    int w = r.Right - r.Left;
                    int h = r.Bottom - r.Top;
                    if (w > 100 && h > 100)
                    {
                        resW = w;
                        resH = h;
                        aspect = (float)w / (float)h;
                    }
                }
            }
            catch (Exception) { }
        }

        void Rect(float cx, float cy, float w, float h, int r, int g, int b, int a)
        {
            Function.Call("DRAW_RECT", cx, cy, w, h, r, g, b, a);
        }

        int SafeFont(int f)
        {
            if (f == 0 || f == 1 || f == 3 || f == 4 || f == 5) return f;
            return 0;
        }

        void DrawTextF(int font, string s, float x, float y, float scale, int r, int g, int b, int a, bool rightAlign, bool centre)
        {
            Function.Call("SET_TEXT_FONT", SafeFont(font));
            Function.Call("SET_TEXT_SCALE", scale, scale);
            Function.Call("SET_TEXT_COLOUR", r, g, b, a);
            Function.Call("SET_TEXT_DROPSHADOW", 1, 0, 0, 0, 255);
            if (rightAlign)
            {
                Function.Call("SET_TEXT_RIGHT_JUSTIFY", 1);
                Function.Call("SET_TEXT_WRAP", 0.0f, x);
            }
            if (centre)
            {
                Function.Call("SET_TEXT_CENTRE", 1);
            }
            Function.Call("DISPLAY_TEXT_WITH_LITERAL_STRING", x, y, "STRING", s);
        }

        void DrawText(string s, float x, float y, float scale, int r, int g, int b, int a, bool rightAlign, bool centre)
        {
            DrawTextF(HudFont, s, x, y, scale, r, g, b, a, rightAlign, centre);
        }

        void DrawPill(float cx, float cy, float h, string label, bool enabled)
        {
            float w = h * 1.4f / aspect;
            int body = enabled ? 95 : 55;
            int txt = enabled ? 255 : 140;
            Rect(cx, cy, w, h * 0.8f, body, body, body, 235);
            DrawText(label, cx, cy - 0.011f, 0.28f, txt, txt, txt, 255, false, true);
        }

        void DrawDpad(float cx, float cy, float h, bool leftArm, bool enabled)
        {
            float w = h / aspect;
            float t = h / 3.0f;
            float tw = w / 3.0f;
            int body = enabled ? 95 : 55;
            int hi = enabled ? 255 : 120;
            Rect(cx, cy, w, t, body, body, body, 235);
            Rect(cx, cy, tw, h, body, body, body, 235);
            if (leftArm) Rect(cx - tw, cy, tw, t, hi, hi, hi, 255);
            else Rect(cx + tw, cy, tw, t, hi, hi, hi, 255);
        }

        float AspectFor(IconKind k)
        {
            if (k == IconKind.LB || k == IconKind.RB) return 91.0f / 52.0f;
            if (k == IconKind.LT || k == IconKind.RT) return 69.0f / 72.0f;
            return 71.0f / 72.0f;
        }

        float HeightFor(IconKind k)
        {
            if (k == IconKind.LB || k == IconKind.RB) return 0.026f * IconScale;
            return 0.030f * IconScale;
        }

        Texture TexFor(IconKind k, bool enabled)
        {
            if (k == IconKind.LB) return enabled ? texLb : texLbOff;
            if (k == IconKind.RB) return enabled ? texRb : texRbOff;
            if (k == IconKind.LT) return texLt;
            if (k == IconKind.RT) return enabled ? texRt : texRtOff;
            if (k == IconKind.DpadLeft) return enabled ? texDl : texDlOff;
            return enabled ? texDr : texDrOff;
        }

        float ColWidth()
        {
            return HeightFor(IconKind.LB) * AspectFor(IconKind.LB) * (float)resH / (float)resW;
        }

        void AddIcon(IconKind k, bool enabled, float cx, float cy)
        {
            Texture t = TexFor(k, enabled);
            if (t != null && !spritesBroken)
            {
                IconCmd c = new IconCmd();
                c.Tex = t;
                c.Aspect = AspectFor(k);
                c.Cx = cx;
                c.Cy = cy;
                c.H = HeightFor(k);
                pending.Add(c);
                return;
            }

            float h = HeightFor(k);
            if (k == IconKind.LB) DrawPill(cx, cy, h, "3", enabled);
            else if (k == IconKind.RB) DrawPill(cx, cy, h, "4", enabled);
            else if (k == IconKind.LT) DrawPill(cx, cy, h, "RMB", true);
            else if (k == IconKind.RT) DrawPill(cx, cy, h, "4", enabled);
            else DrawDpad(cx, cy, h, k == IconKind.DpadLeft, enabled);
        }

        void DrawRow(float rightEdge, float cy, string label, bool enabled, IconKind kind)
        {
            float colW = ColWidth();
            float iconCx = rightEdge - colW * 0.5f;
            float textRight = rightEdge - colW - 0.008f;

            if (!AddTextSprite(enabled ? label : label + "_off", textRight, cy, OptionTextHeight))
            {
                int c = enabled ? 235 : 125;
                int a = enabled ? 255 : 170;
                DrawText(ES(label), textRight, cy - 0.0717f * OptionScale + TextYOffset, OptionScale, c, c, c, a, true, false);
            }
            AddIcon(kind, enabled, iconCx, cy);
        }

        void DrawMenu(float rightEdge, float yTop, bool full, bool robOk, bool greetOk, bool tauntOk, string label)
        {
            DrawMenu(rightEdge, yTop, full, robOk, greetOk, tauntOk, label, false);
        }

        void DrawMenu(float rightEdge, float yTop, bool full, bool robOk, bool greetOk, bool tauntOk, string label, bool sellRow)
        {
            float y = yTop;
            if (full && sellRow) y -= RowStep;       // one row more: start higher so the name stays put
            DrawRow(rightEdge, y, "Rob", robOk, IconKind.LB);
            if (full)
            {
                if (sellRow)
                {
                    // Pusher buyer: Sell sits right under Rob
                    y += RowStep;
                    DrawRow(rightEdge, y, "Sell", true, IconKind.RT);
                }
                y += RowStep;
                DrawRow(rightEdge, y, "Greet", greetOk, IconKind.DpadLeft);
                y += RowStep;
                DrawRow(rightEdge, y, "Taunt", tauntOk, IconKind.DpadRight);
            }

            float divY = y + RowStep * 0.62f;
            Rect(rightEdge - 0.075f, divY, 0.15f, 0.0016f, 255, 255, 255, 190);

            float nameY = y + RowStep * 1.22f;
            float colW = ColWidth();
            float nameRight = full ? (rightEdge - colW - 0.008f) : rightEdge;
            if (!AddTextSprite("name:" + label, nameRight, nameY, NameTextHeight))
                DrawText(label, nameRight, nameY - 0.0717f * NameScale + TextYOffset, NameScale, 255, 255, 255, 255, true, false);
            if (full) AddIcon(IconKind.LT, true, rightEdge - colW * 0.5f, nameY);
        }

        void DrawHud(int mode, bool robOk, bool greetOk, bool tauntOk, string label)
        {
            DrawHud(mode, robOk, greetOk, tauntOk, label, false);
        }

        void DrawHud(int mode, bool robOk, bool greetOk, bool tauntOk, string label, bool sellRow)
        {
            if (mode == 1) DrawMenu(RightEdge, RightTop, true, robOk, greetOk, tauntOk, label, sellRow);
            else DrawMenu(RightEdge, RightTop + 2.0f * RowStep, false, robOk, false, false, label);
        }

        void OnDraw(object sender, GraphicsEventArgs e)
        {
            if (spritesBroken) return;
            List<IconCmd> cmds = iconCmds;
            if (cmds.Count == 0) return;
            try
            {
                foreach (IconCmd c in cmds)
                {
                    float h = c.H * (float)resH;
                    float w = h * c.Aspect;
                    float x = c.Cx * (float)resW - w * 0.5f;
                    float y = c.Cy * (float)resH - h * 0.5f;
                    if (SpriteOriginIsCenter) { x += w * 0.5f; y += h * 0.5f; }
                    e.Graphics.DrawSprite(c.Tex, x, y, w, h, 0.0f);
                }
            }
            catch (Exception ex)
            {
                spritesBroken = true;
                Log("DrawSprite failed, switching to fallback icons: " + ex.Message);
            }
        }

        void OnTick(object sender, EventArgs e)
        {
            pending = new List<IconCmd>();
            try { Update(); }
            catch (Exception ex) { Log("Update error: " + ex.ToString()); }
            iconCmds = pending;
        }

        void Update()
        {
            if (DebugStage <= 1) return;
            PusherHeartbeat();

            long now = Now();
            RunJobs(now);
            PurgeStates(now);
            UpdateResolution();

            int pollIdx = 0;
            try { pollIdx = Function.Call<int>("GET_PLAYER_ID"); }
            catch (Exception ex) { LogOnce("pid", "GET_PLAYER_ID failed: " + ex.Message); }
            BlockedByGameState(pollIdx);

            Ped player = Player.Character;
            bool focused = GameHasFocus();
            Inp inp = ReadInput(focused);

            if (DebugStage >= 3) ReleaseHoldsIfFiring(inp.Fire, now);

            bool pressGreet = inp.Greet && !prevGreet;
            bool pressTaunt = inp.Taunt && !prevTaunt;
            bool pressRob = inp.Rob && !prevRob;
            bool pressFace = inp.Face && !prevFace;
            bool pressSell = (inp.Sell && !prevSell) || (inp.Fire && !prevFireSell);   // RT (or keyboard 4): Buy / Sell
            prevSell = inp.Sell;
            prevFireSell = inp.Fire;
            prevGreet = inp.Greet;
            prevTaunt = inp.Taunt;
            prevRob = inp.Rob;
            prevFace = inp.Face;

            // nothing at all during a mission (the aggro reactions included)
            if (missionCached) { fightMode = false; lastMode = 0; return; }

            if (DebugStage >= 3 && Game.Exists(player) && player.isAliveAndWell)
            {
                if (inp.Fire || inp.Face) playerAttackUntil = now + 2000;
                if (now >= nextAggroScan)
                {
                    nextAggroScan = now + 100;
                    try { ScanAggro(player, World.GetPeds(player.Position, 15.0f), now, playerAttackUntil > now); }
                    catch (Exception ex) { LogOnce("aggroscan", "Aggro scan failed: " + ex.Message); }
                }
            }

            if (!inp.Aim)
            {
                fightMode = false;
                lastMode = 0;
                return;
            }

            if (!Game.Exists(player) || !player.isAliveAndWell) return;
            if (player.isInVehicle()) return;

            if (pressFace && lastMode == 1) fightMode = true;
            if (fightMode) return;
            if (PusherBusy()) { lastMode = 0; return; }        // a Pusher menu or scene is up

            int playerIdx = 0;
            try { playerIdx = Function.Call<int>("GET_PLAYER_ID"); }
            catch (Exception ex) { LogOnce("pid", "GET_PLAYER_ID failed: " + ex.Message); }

            if (BlockedByGameState(playerIdx)) { lastMode = 0; return; }

            Ped[] peds = World.GetPeds(player.Position, AggroScanRadius);
            if (DebugStage >= 3 && WantedNow()) { lastMode = 0; return; }

            int mode;
            Ped target = FindTarget(player, playerIdx, peds, out mode);
            lastMode = mode;
            if (target == null) return;

            PedState st = GetState(target, now);

            if (DebugStage >= 3 && st.AggroUntil > now) { lastMode = 0; return; }

            // Pusher dealers: Buy Drugs when locked on, Rob at gunpoint. No greet / taunt.
            if (PusherIsDealer(target))
            {
                Vector3 dtp = target.Position;
                Vector3 dpp = player.Position;
                float ddx = dtp.X - dpp.X, ddy = dtp.Y - dpp.Y, ddz = dtp.Z - dpp.Z;
                bool dealerNear = (ddx * ddx + ddy * ddy + ddz * ddz) <= StickupRadius * StickupRadius;
                bool dealerArmed = HasGunInHand(target);
                if (mode == 2 && (!dealerNear || dealerArmed)) { lastMode = 0; return; }
                bool dealerRobOk = !st.Robbed;
                if (mode == 1) DrawDealerMenu();
                else DrawMenu(RightEdge, RightTop + 2.0f * RowStep, false, dealerRobOk, false, false, PusherDealerLabel);
                if (HoldWhileAiming && mode == 2 && dealerRobOk) KeepGunpointHold(target, st, now);
                if (now < busyUntil) return;
                if (mode == 1 && pressSell) PusherOpenDealer(target);
                else if (mode == 2 && pressRob && dealerRobOk) DoRobDealer(target, st, now);
                return;
            }
            bool sellOk = mode == 1 && PusherIsBuyer(target);

            if (st.GreetLockUntil > 0 && now >= st.GreetLockUntil)
            {
                st.GreetLockUntil = 0;
                st.GreetCount = 0;
            }
            if (st.TauntLockUntil > 0 && now >= st.TauntLockUntil)
            {
                st.TauntLockUntil = 0;
                st.TauntCount = 0;
            }

            bool receptive = now >= st.DisengagedUntil;
            bool greetOk = receptive && st.GreetLockUntil == 0;
            bool tauntOk = receptive && st.TauntLockUntil == 0;
            Vector3 tp = target.Position;
            Vector3 pp2 = player.Position;
            float sx = tp.X - pp2.X;
            float sy = tp.Y - pp2.Y;
            float sz = tp.Z - pp2.Z;
            bool near = (sx * sx + sy * sy + sz * sz) <= StickupRadius * StickupRadius;
            bool armed = HasGunInHand(target);
            if (mode == 2 && (!near || armed)) { lastMode = 0; return; }
            bool robOk = receptive && !st.Robbed && near && !armed;

            DrawHud(mode, robOk, greetOk, tauntOk, LabelFor(target, st), sellOk);

            if (HoldWhileAiming && mode == 2 && robOk) KeepGunpointHold(target, st, now);

            if (now < busyUntil) return;

            if (mode == 1)
            {
                if (pressSell && sellOk) PusherSell(target, LabelFor(target, st));
                else if (pressGreet && greetOk) DoGreet(target, st, now);
                else if (pressTaunt && tauntOk) DoTaunt(target, st, now);
                else if (pressRob && robOk) DoRob(target, st, now);
            }
            else
            {
                if (pressRob && robOk) DoRob(target, st, now);
            }
        }
    }
}
